// Extract donor data from Stripe checkout.session.completed payload
const obj = $input.first().json.body?.data?.object || {};

const rawName   = obj.customer_details?.name  || '';
const rawEmail  = obj.customer_details?.email || '';
const amountRaw = obj.amount_total || 0;
const created   = obj.created || Math.floor(Date.now() / 1000);

const donor_name   = rawName.trim() || 'Valued Supporter';
const donor_email  = rawEmail.trim();
const amount_usd   = (amountRaw / 100).toFixed(2);
const payment_id   = obj.id || 'N/A';
const is_monthly   = obj.mode === 'subscription';
const donation_type = is_monthly ? 'Monthly Recurring' : 'One-Time';
const payment_date  = new Date(created * 1000).toLocaleDateString('en-US', {
  year: 'numeric', month: 'long', day: 'numeric'
});

if (!donor_email) {
  throw new Error('No donor email found in Stripe payload');
}

return [{ json: { donor_name, donor_email, amount_usd, payment_id, donation_type, payment_date, is_monthly } }];
